/* Pasajes estoicos y de superación personal: una lista de 50 reglas para vivir,
 * más líneas clásicas de Marco Aurelio, Séneca y Epicteto. Incluyen acentos,
 * ñ y signos de apertura ¿ ¡ a propósito. `length` se deriva al cargar. */
(function (TT) {
  'use strict';

  var REGLAS = 'Ryan Holiday, reglas de vida';
  var EGO = 'Ryan Holiday, El ego es el enemigo';

  var QUOTES = [
    { text: 'Concéntrate en lo que puedes controlar.', source: REGLAS },
    { text: 'Medita sobre tu mortalidad todos los días.', source: REGLAS },
    { text: 'Haz tuya la mañana.', source: REGLAS },
    { text: 'Piensa en el progreso, no en la perfección.', source: REGLAS },
    { text: 'Cuando leas, pregúntate: ¿qué pienso hacer con esta información?', source: REGLAS },
    { text: 'Valora el tiempo más que el dinero y las posesiones.', source: REGLAS },
    { text: 'Intenta encontrar lo bueno en las personas.', source: REGLAS },
    { text: 'Que nunca te escuchen quejarte, ni siquiera a ti mismo.', source: REGLAS },
    { text: 'Escucha más de lo que hablas.', source: REGLAS },
    { text: 'Sé estricto contigo mismo y tolerante con los demás.', source: REGLAS },
    { text: 'Trata al cuerpo con rigor para que obedezca mejor a la mente.', source: REGLAS },
    { text: 'Aprende algo de cada persona.', source: REGLAS },
    { text: 'Define qué significa el éxito para ti.', source: REGLAS },
    { text: 'No tengas miedo de pedir ayuda.', source: REGLAS },
    { text: 'Encuentra cada día una cosa que te haga más sabio.', source: REGLAS },
    { text: 'Estudia a los grandes. Súbete a hombros de gigantes.', source: REGLAS },
    { text: 'Encuentra la belleza en las cosas comunes.', source: REGLAS },
    { text: 'Júntate con gente que te haga mejor.', source: REGLAS },
    { text: 'Júntate con gente a la que puedas hacer mejor.', source: REGLAS },
    { text: 'No mires las noticias.', source: REGLAS },
    { text: 'Haz un acto de bondad cada día.', source: REGLAS },
    { text: 'Recoge la basura cuando la veas.', source: REGLAS },
    { text: 'No busques aprobación fuera de ti.', source: REGLAS },
    { text: 'Pasa tiempo con las personas mayores.', source: REGLAS },
    { text: 'Al evaluar una oportunidad, pregúntate: ¿qué me va a enseñar más?', source: REGLAS },
    { text: 'Intenta ser diferente, no mejor.', source: REGLAS },
    { text: 'Aparta de tu vida a las personas tóxicas.', source: REGLAS },
    { text: 'Deja los lugares mejor de lo que los encontraste.', source: REGLAS },
    { text: 'Pasa tiempo en librerías.', source: REGLAS },
    { text: 'Trabaja duro, mantente sano y guarda silencio. No es la ambición ni el talento lo que te va a distinguir, sino la cordura. El silencio es poder.', source: REGLAS },
    { text: 'Pregúntate: ¿estoy usando esta tecnología, o me está usando a mí?', source: REGLAS },
    { text: 'Vive una vida interesante.', source: REGLAS },
    { text: 'Recuerda: nadie está pensando en ti. Están demasiado ocupados pensando en sí mismos.', source: REGLAS },
    { text: 'No leas libros solamente: reléelos.', source: REGLAS },
    { text: 'No hables de tus proyectos hasta haberlos terminado.', source: REGLAS },
    { text: 'Ve oportunidades donde otros ven obstáculos.', source: REGLAS },
    { text: 'Imprime los buenos consejos y ponlos donde trabajas.', source: REGLAS },
    { text: 'Si un libro es malo, deja de leerlo.', source: REGLAS },
    { text: 'Acepta parecer despistado o tonto.', source: REGLAS },
    { text: 'Haz bien tu trabajo, sea cual sea, porque como haces una cosa es como lo haces todo.', source: REGLAS },
    { text: 'Renuncia a la idea de vengarte.', source: REGLAS },
    { text: 'Antes de actuar con ira, espera.', source: REGLAS },
    { text: 'No elijas la infelicidad por miedo a la incertidumbre.', source: REGLAS },
    { text: 'En vez de creer en ti mismo, genera evidencia.', source: REGLAS },
    { text: 'Nunca creas que ya lo tienes todo resuelto.', source: REGLAS },
    { text: 'Concéntrate en el momento, no en los monstruos que puede que haya o no más adelante.', source: REGLAS },
    { text: 'Vete a dormir de una vez.', source: REGLAS },
    { text: 'Relájate. Sea lo que sea, probablemente te lo estás tomando demasiado en serio.', source: REGLAS },
    { text: 'Sal a caminar.', source: REGLAS },
    { text: 'Haz un poco de progreso cada día.', source: REGLAS },

    { text: 'Ningún viento es favorable para el que no sabe a qué puerto va.', source: 'Séneca, Cartas a Lucilio' },
    { text: 'Es una vergüenza envejecer sin ver la belleza y la fuerza de las que tu cuerpo es capaz.', source: 'Sócrates, según Jenofonte' },
    { text: 'Tienes poder sobre tu mente, no sobre los acontecimientos externos. Comprende esto y encontrarás la fuerza.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'No pierdas más tiempo discutiendo cómo debe ser un hombre bueno. Sé uno.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Muy poco se necesita para una vida feliz; todo está dentro de ti, en tu manera de pensar.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Cuando te levantes por la mañana, piensa en el precioso privilegio de estar vivo: de respirar, de pensar, de disfrutar, de amar.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Lo que impide la acción hace avanzar la acción. Lo que se interpone en el camino se convierte en el camino.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Si no es correcto, no lo hagas; si no es verdad, no lo digas.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'No actúes como si fueras a vivir diez mil años. Mientras vivas, mientras esté en tu poder, sé bueno.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'La mejor venganza es no parecerte a quien te hizo daño.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Limítate al presente.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Mira bien dentro de ti; ahí hay una fuente de fuerza que brotará siempre que mires.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Al amanecer, cuando te cueste salir de la cama, dite a ti mismo: tengo que ir a trabajar como ser humano. ¿De qué me quejo, si voy a hacer aquello para lo que nací, las cosas para las que fui traído al mundo? ¿O acaso fui creado para esto: para quedarme abrigado debajo de las mantas?', source: 'Marco Aurelio, Meditaciones' },
    { text: 'No es que tengamos poco tiempo para vivir, sino que desperdiciamos mucho. La vida es lo bastante larga para las metas más altas, si se invirtiera toda bien.', source: 'Séneca, Sobre la brevedad de la vida' },
    { text: 'Posponer las cosas es el mayor desperdicio de vida: arrebata cada día a medida que llega y nos niega el presente prometiéndonos el futuro. Todo el futuro descansa en la incertidumbre: vive de inmediato. La espera es el mayor impedimento para vivir: por anticipar el mañana, se pierde el hoy.', source: 'Séneca, Sobre la brevedad de la vida' },
    { text: 'Sufrimos más en la imaginación que en la realidad.', source: 'Séneca, Cartas a Lucilio' },
    { text: 'La suerte es lo que sucede cuando la preparación se encuentra con la oportunidad.', source: 'Atribuida a Séneca' },
    { text: 'Cada noche, antes de dormir, preguntémonos: ¿qué debilidad vencí hoy? ¿Qué virtud adquirí?', source: 'Séneca, Sobre la ira' },
    { text: 'No importa lo que te sucede, sino cómo reaccionas a ello.', source: 'Epicteto' },
    { text: 'Ningún hombre es libre si no es dueño de sí mismo.', source: 'Epicteto' },
    { text: 'No expliques tu filosofía. Encárnala.', source: 'Epicteto' },
    { text: 'Tenemos dos orejas y una boca para escuchar el doble de lo que hablamos.', source: 'Epicteto' },
    { text: 'Primero dite a ti mismo qué quieres ser; luego haz lo que tengas que hacer.', source: 'Epicteto, Disertaciones' },
    { text: 'No pidas que las cosas sucedan como tú quieres; quiere que sucedan como suceden, y tu vida tendrá un curso sereno.', source: 'Epicteto, Enquiridión' },

    { text: 'Contempla la belleza de la vida. Mira las estrellas, y mírate corriendo con ellas.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'La felicidad de tu vida depende de la calidad de tus pensamientos.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Cuánto tiempo gana el que no mira lo que dice, hace o piensa su vecino.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'No es la muerte lo que un hombre debe temer; debe temer no empezar nunca a vivir.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Acepta las cosas a las que el destino te ata, y ama a las personas que el destino pone a tu lado.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'El alma se tiñe del color de sus pensamientos.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Lo que hacemos ahora resuena en la eternidad.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Sé como el acantilado contra el que rompen las olas sin descanso: se mantiene firme y doma la furia del agua a su alrededor.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Si algo externo te angustia, el dolor no se debe a la cosa misma sino a tu juicio sobre ella, y está en tu poder revocar ese juicio en cualquier momento.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Recibe sin orgullo, suelta sin apego.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Hoy escapé de la ansiedad. O no: la descarté, porque estaba dentro de mí, en mis propias percepciones, no afuera.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Piénsate muerto. Ya viviste tu vida. Ahora toma lo que queda y vívelo como corresponde.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'En ningún lugar encuentra el hombre un retiro más tranquilo y sereno que en su propia alma.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Haz cada acto de tu vida como si fuera el último acto de tu vida.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'El valor de un hombre no es mayor que el valor de sus ambiciones.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Regálate algo: el momento presente.', source: 'Marco Aurelio, Meditaciones' },

    { text: 'Empieza a vivir de una vez, y cuenta cada día como una vida entera.', source: 'Séneca' },
    { text: 'Las dificultades fortalecen la mente, como el trabajo fortalece el cuerpo.', source: 'Séneca' },
    { text: 'El que es valiente es libre.', source: 'Séneca' },
    { text: 'Sufre más de lo necesario el que sufre antes de que sea necesario.', source: 'Séneca' },
    { text: 'Mientras posponemos, la vida pasa de largo.', source: 'Séneca' },
    { text: 'Nadie llegó a sabio por casualidad.', source: 'Séneca' },
    { text: 'Es un camino áspero el que lleva a las cumbres de la grandeza.', source: 'Séneca' },
    { text: 'La vida es como una historia: no importa lo larga que sea, sino lo buena que sea.', source: 'Séneca' },
    { text: 'Donde hay un ser humano, hay una oportunidad para la bondad.', source: 'Séneca' },
    { text: 'La vida es muy corta y ansiosa para quienes olvidan el pasado, descuidan el presente y temen el futuro.', source: 'Séneca, Sobre la brevedad de la vida' },
    { text: 'Quien teme a la muerte nunca hará nada digno de un hombre vivo.', source: 'Séneca' },
    { text: 'Actúan como mortales en todo lo que temen, y como inmortales en todo lo que desean.', source: 'Séneca, Sobre la brevedad de la vida' },
    { text: 'Una gema no puede pulirse sin fricción, ni un hombre perfeccionarse sin pruebas.', source: 'Séneca' },
    { text: 'La mente ansiosa por lo que vendrá es desdichada.', source: 'Séneca' },
    { text: 'Es poder de la mente ser inconquistable.', source: 'Séneca' },
    { text: 'No es pobre el que tiene poco, sino el que ansía más.', source: 'Séneca, Cartas a Lucilio' },
    { text: 'Nada demuestra mejor una mente ordenada que la capacidad de un hombre de detenerse donde está y pasar un tiempo en su propia compañía.', source: 'Séneca, Cartas a Lucilio' },

    { text: '¿Cuánto tiempo más vas a esperar para exigirte lo mejor de ti mismo?', source: 'Epicteto' },
    { text: 'Si quieres mejorar, confórmate con parecer necio y tonto.', source: 'Epicteto' },
    { text: 'La riqueza no consiste en tener grandes posesiones, sino en tener pocas necesidades.', source: 'Epicteto' },
    { text: 'Es imposible que un hombre aprenda lo que cree que ya sabe.', source: 'Epicteto' },
    { text: 'Las circunstancias no hacen al hombre; sólo lo revelan ante sí mismo.', source: 'Epicteto' },
    { text: 'La clave es rodearte sólo de gente que te eleve, cuya presencia saque lo mejor de ti.', source: 'Epicteto' },
    { text: 'Sólo los educados son libres.', source: 'Epicteto' },
    { text: 'Sabio es el que no se lamenta por lo que le falta, sino que se alegra por lo que tiene.', source: 'Epicteto' },
    { text: 'Haz el mejor uso de lo que está en tu poder, y toma el resto como venga.', source: 'Epicteto' },
    { text: 'Al hombre no lo preocupan tanto los problemas reales como sus ansiedades imaginadas sobre los problemas reales.', source: 'Epicteto' },
    { text: 'Culpar a otros de las propias desgracias es señal de falta de educación. Culparse a uno mismo muestra que la educación ha comenzado.', source: 'Epicteto' },
    { text: 'La libertad es la única meta digna de la vida. Se gana desatendiendo las cosas que están más allá de nuestro control.', source: 'Epicteto' },
    { text: 'Algunas cosas están bajo nuestro control y otras no. Bajo nuestro control están la opinión, el impulso, el deseo, la aversión y, en una palabra, todo lo que es acción nuestra. Fuera de nuestro control están el cuerpo, la propiedad, la reputación, el mando y, en una palabra, todo lo que no es acción nuestra.', source: 'Epicteto, Enquiridión' },

    { text: 'El hombre conquista el mundo conquistándose a sí mismo.', source: 'Zenón de Citio' },
    { text: 'Mejor tropezar con los pies que con la lengua.', source: 'Zenón de Citio' },
    { text: 'Los hados guían al que quiere, y arrastran al que no quiere.', source: 'Cleantes' },
    { text: 'El carácter es destino.', source: 'Heráclito' },
    { text: 'Una vida sin examen no merece ser vivida.', source: 'Sócrates, según Platón' },
    { text: 'Somos lo que hacemos repetidamente. La excelencia, entonces, no es un acto, sino un hábito.', source: 'Atribuida a Aristóteles' },

    { text: 'Nunca dejes que el futuro te perturbe. Lo enfrentarás, si hace falta, con las mismas armas de la razón que hoy te defienden del presente.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Cuando despiertes por la mañana, dite a ti mismo: las personas con las que trataré hoy serán entrometidas, ingratas, arrogantes, deshonestas, envidiosas y hurañas. Son así porque no saben distinguir el bien del mal. Pero yo he visto la belleza del bien y la fealdad del mal.', source: 'Marco Aurelio, Meditaciones' },
    { text: 'Todo lo que oyes es una opinión, no un hecho. Todo lo que ves es una perspectiva, no la verdad. Las cosas en las que piensas determinan la calidad de tu mente. Tu alma toma el color de tus pensamientos.', source: 'Atribuida a Marco Aurelio' },
    { text: 'Hasta que empezamos a prescindir de ellas, no nos damos cuenta de lo innecesarias que son muchas cosas. Las usábamos no porque las necesitáramos, sino porque las teníamos.', source: 'Séneca, Cartas a Lucilio' },
    { text: 'Reserva cierto número de días para contentarte con la comida más escasa y barata, con ropa tosca y áspera, mientras te dices: ¿es esta la condición que yo temía?', source: 'Séneca, Cartas a Lucilio' },
    { text: 'Piensa tu camino a través de las dificultades: las condiciones duras pueden ablandarse, las estrechas pueden ensancharse, y las pesadas pesan menos sobre quien sabe llevarlas.', source: 'Séneca, Sobre la tranquilidad del ánimo' },
    { text: 'Nadie puede progresar mientras vacila entre cosas opuestas.', source: 'Epicteto' },
    { text: 'Pregúntate: ¿esta impresión concierne a las cosas que están bajo mi control, o a las que no? Y si concierne a algo fuera de tu control, prepárate para decir que no es nada para ti.', source: 'Epicteto, Enquiridión' },

    { text: 'Sé un anteambulo. Despeja el camino a quienes están por encima de ti y con el tiempo abrirás un camino para ti mismo.', source: EGO },
    { text: 'Para llegar a ser grande, todo luchador necesita a alguien mejor de quien aprender, a alguien menor a quien enseñar y a alguien igual con quien medirse.', source: EGO },
    { text: 'Si ya no estás aprendiendo, ya estás muriendo.', source: EGO },
    { text: 'La pasión es forma por encima de función. El propósito es función, función y función.', source: EGO },
    { text: 'Entrenar es como barrer el suelo. Haberlo hecho una vez no lo deja limpio para siempre. Cada día vuelve el polvo. Cada día hay que barrer. Con el ego pasa lo mismo.', source: EGO },
    { text: 'Cada día del resto de tu vida te encontrarás en una de estas tres fases: aspiración, éxito, fracaso. En todas ellas tendrás que luchar contra el ego.', source: EGO },
    { text: 'Cuando no estés practicando, recuerda: alguien en algún lugar está practicando, y cuando te encuentres con él, te ganará.', source: EGO },
    { text: 'No puedes construir una reputación sobre lo que vas a hacer.', source: 'Henry Ford, citado en El ego es el enemigo' },
    { text: 'Un gran destino es una gran esclavitud.', source: 'Séneca, citado en El ego es el enemigo' },
    { text: '¿Y por qué habríamos de enfadarnos con el mundo? ¡Como si el mundo se diera cuenta!', source: 'Eurípides, citado en El ego es el enemigo' },
    { text: 'Uno de los síntomas de una crisis nerviosa inminente es la creencia de que el propio trabajo es tremendamente importante.', source: 'Bertrand Russell, La conquista de la felicidad' },
    { text: 'Te estás convirtiendo en quien vas a ser, así que más vale que no seas un imbécil.', source: 'Cheryl Strayed, citada en El ego es el enemigo' },
    { text: 'Cuando miro al universo, sé que soy pequeño, pero también soy grande. Soy grande porque estoy conectado al universo y el universo está conectado a mí.', source: 'Neil deGrasse Tyson, citado en El ego es el enemigo' }
  ];

  /* Sized for aphorisms rather than literary passages: a quick line, a
   * sentence or two, a full thought. */
  function classify(n) {
    if (n < 60) return 'short';
    if (n <= 150) return 'medium';
    return 'long';
  }

  TT.data = TT.data || {};
  TT.data.quotes = TT.data.quotes || {};
  TT.data.quotes.es = QUOTES.map(function (q) {
    return { text: q.text, source: q.source, chars: q.text.length, length: classify(q.text.length) };
  });
})(window.TT = window.TT || {});
